import { sql } from 'drizzle-orm';
import {
  char,
  check,
  customType,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core';
import type { Utm } from '@byb/schemas/waitlist';

/**
 * SCHEMA §12 specifies citext for email columns; Drizzle has no built-in, so the
 * type is declared here. The extension is created by the first migration.
 */
const citext = customType<{ data: string }>({
  dataType() {
    return 'citext';
  },
});

/** TR-CONV-01: IDs are uuidv7, generated by the database (PostgreSQL 18). */
const uuidv7Pk = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

/** SCHEMA §12 */
export const waitlistSignups = pgTable('waitlist_signups', {
  id: uuidv7Pk(),
  email: citext('email').notNull().unique(),
  source: text('source'),
  utm: jsonb('utm').$type<Utm>(),
  referrer: text('referrer'),
  // DEC-039: the product name from /notify?q=, recorded only when source is 'search'.
  query: text('query'),
  // LEGAL-08: records which consent sentence this person agreed to.
  consentTextVersion: text('consent_text_version').notNull(),
  confirmedAt: timestamp('confirmed_at', { withTimezone: true }),
  createdAt: createdAt(),
});

/**
 * SCHEMA §12. `stripe_checkout_session_id` keeps its documented name even
 * though M0 runs the mock payment provider, which writes `mock_cs_<uuid>`
 * there — forking the column would make the schema doc untrue for the sake of
 * a prefix. Its UNIQUE constraint is what makes the webhook idempotent.
 */
export const preorders = pgTable(
  'preorders',
  {
    id: uuidv7Pk(),
    email: citext('email').notNull(),
    stripeCheckoutSessionId: text('stripe_checkout_session_id').notNull().unique(),
    stripePaymentIntentId: text('stripe_payment_intent_id'),
    amountCents: integer('amount_cents').notNull(),
    currency: char('currency', { length: 3 }).notNull().default('USD'),
    offerCode: text('offer_code').notNull(),
    status: text('status').notNull(),
    createdAt: createdAt(),
    refundedAt: timestamp('refunded_at', { withTimezone: true }),
  },
  (t) => [check('preorders_status_check', sql`${t.status} IN ('paid', 'refunded')`)],
);

export type WaitlistSignup = typeof waitlistSignups.$inferSelect;
export type Preorder = typeof preorders.$inferSelect;
